{
  "specVersion": "0.2.0-draft",
  "id": "https://example.org/judgment-packs/vendor-approval-policy",
  "version": "1.0.0",
  "title": "Vendor Approval Policy",
  "description": "Determines vendor onboarding spend requests under the stated financial-evidence precondition, sanctions rules, supplier overrides, approval thresholds, and unreadable-input semantics.",
  "decision": {
    "intent": "Determine the disposition of a vendor onboarding spend request.",
    "question": "Should the vendor request be approved, reviewed, enhanced-reviewed, rejected, or left unresolved?"
  },
  "evidenceRequirements": [
    {
      "id": "financial-evidence",
      "description": "Audited financial statements must be available before any determination can be issued.",
      "required": true,
      "kind": "document"
    },
    {
      "id": "insurance-certificate",
      "description": "Insurance certificate consulted only for qualifying D6b requests.",
      "required": false,
      "kind": "document"
    }
  ],
  "outcomes": [
    {
      "id": "approve",
      "label": "Approve"
    },
    {
      "id": "review",
      "label": "Review"
    },
    {
      "id": "enhanced-review",
      "label": "Enhanced review"
    },
    {
      "id": "reject",
      "label": "Reject"
    }
  ],
  "rules": [
    {
      "id": "r-d1-sanctions-match",
      "description": "D1 rejects a sanctions match.",
      "when": {
        "op": "fact",
        "path": "/vendor/sanctionsStatus",
        "operator": "equals",
        "value": "MATCH"
      },
      "outcome": "reject",
      "onUnknown": "ignore"
    },
    {
      "id": "r-d3-critical-risk",
      "description": "D3 rejects a clear-screened request with risk score at least 90.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "fact",
            "path": "/vendor/riskScore",
            "operator": "greater-than-or-equal",
            "value": "90"
          }
        ]
      },
      "outcome": "reject",
      "onUnknown": "ignore"
    },
    {
      "id": "r-d4-high-country-elevated-risk",
      "description": "D4 rejects a clear-screened request in a high-risk country with risk score at least 70.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "fact",
            "path": "/vendor/countryRisk",
            "operator": "equals",
            "value": "HIGH"
          },
          {
            "op": "fact",
            "path": "/vendor/riskScore",
            "operator": "greater-than-or-equal",
            "value": "70"
          }
        ]
      },
      "outcome": "reject",
      "onUnknown": "ignore"
    },
    {
      "id": "r-d5-prior-enforcement",
      "description": "D5 rejects a clear-screened vendor with a recorded prior enforcement action.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "fact",
            "path": "/vendor/priorEnforcement",
            "operator": "equals",
            "value": "yes"
          }
        ]
      },
      "outcome": "reject",
      "onUnknown": "ignore"
    },
    {
      "id": "r-d6a-low-risk-low-spend",
      "description": "D6a approves a low-country-risk request with risk below 40 and spend at most 500000 dollars.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "fact",
            "path": "/vendor/countryRisk",
            "operator": "equals",
            "value": "LOW"
          },
          {
            "op": "fact",
            "path": "/vendor/riskScore",
            "operator": "less-than",
            "value": "40"
          },
          {
            "op": "fact",
            "path": "/vendor/requestedSpend",
            "operator": "less-than-or-equal",
            "value": "500000.00"
          }
        ]
      },
      "outcome": "approve",
      "onUnknown": "ignore"
    },
    {
      "id": "r-d6b-insured",
      "description": "D6b approves a qualifying low-risk-country request when its insurance certificate is available.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "fact",
            "path": "/vendor/countryRisk",
            "operator": "equals",
            "value": "LOW"
          },
          {
            "op": "fact",
            "path": "/vendor/riskScore",
            "operator": "less-than",
            "value": "40"
          },
          {
            "op": "fact",
            "path": "/vendor/requestedSpend",
            "operator": "greater-than",
            "value": "500000.00"
          },
          {
            "op": "fact",
            "path": "/vendor/requestedSpend",
            "operator": "less-than-or-equal",
            "value": "2000000.00"
          },
          {
            "op": "evidence-present",
            "evidenceRequirement": "insurance-certificate"
          }
        ]
      },
      "outcome": "approve",
      "onUnknown": "ignore"
    },
    {
      "id": "r-d6b-uninsured",
      "description": "D6b sends a qualifying low-risk-country request to enhanced review when its insurance certificate is absent.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "fact",
            "path": "/vendor/countryRisk",
            "operator": "equals",
            "value": "LOW"
          },
          {
            "op": "fact",
            "path": "/vendor/riskScore",
            "operator": "less-than",
            "value": "40"
          },
          {
            "op": "fact",
            "path": "/vendor/requestedSpend",
            "operator": "greater-than",
            "value": "500000.00"
          },
          {
            "op": "fact",
            "path": "/vendor/requestedSpend",
            "operator": "less-than-or-equal",
            "value": "2000000.00"
          },
          {
            "op": "not",
            "condition": {
              "op": "evidence-present",
              "evidenceRequirement": "insurance-certificate"
            }
          }
        ]
      },
      "outcome": "enhanced-review",
      "onUnknown": "ignore"
    },
    {
      "id": "r-d6c-low-moderate-small",
      "description": "D6c approves an established low-country-risk vendor with risk from 40 through 69 and spend at most 100000 dollars.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "fact",
            "path": "/vendor/countryRisk",
            "operator": "equals",
            "value": "LOW"
          },
          {
            "op": "fact",
            "path": "/vendor/riskScore",
            "operator": "greater-than-or-equal",
            "value": "40"
          },
          {
            "op": "fact",
            "path": "/vendor/riskScore",
            "operator": "less-than",
            "value": "70"
          },
          {
            "op": "fact",
            "path": "/vendor/requestedSpend",
            "operator": "less-than-or-equal",
            "value": "100000.00"
          }
        ]
      },
      "outcome": "approve",
      "onUnknown": "ignore"
    },
    {
      "id": "r-o1-new-vendor-review",
      "description": "O1 sends a new vendor that otherwise satisfies D6c to review.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "fact",
            "path": "/vendor/countryRisk",
            "operator": "equals",
            "value": "LOW"
          },
          {
            "op": "fact",
            "path": "/vendor/riskScore",
            "operator": "greater-than-or-equal",
            "value": "40"
          },
          {
            "op": "fact",
            "path": "/vendor/riskScore",
            "operator": "less-than",
            "value": "70"
          },
          {
            "op": "fact",
            "path": "/vendor/requestedSpend",
            "operator": "less-than-or-equal",
            "value": "100000.00"
          },
          {
            "op": "fact",
            "path": "/vendor/newVendor",
            "operator": "equals",
            "value": "yes"
          }
        ]
      },
      "outcome": "review",
      "onUnknown": "ignore"
    },
    {
      "id": "r-d7-medium-low-risk-small",
      "description": "D7 approves a medium-country-risk request with risk below 40 and spend at most 100000 dollars.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "fact",
            "path": "/vendor/countryRisk",
            "operator": "equals",
            "value": "MEDIUM"
          },
          {
            "op": "fact",
            "path": "/vendor/riskScore",
            "operator": "less-than",
            "value": "40"
          },
          {
            "op": "fact",
            "path": "/vendor/requestedSpend",
            "operator": "less-than-or-equal",
            "value": "100000.00"
          }
        ]
      },
      "outcome": "approve",
      "onUnknown": "ignore"
    },
    {
      "id": "r-d8-review",
      "description": "D8 reviews every clear-screened request not falling within another ordinary determination region.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "not",
            "condition": {
              "op": "any",
              "conditions": [
                {
                  "op": "all",
                  "conditions": [
                    {
                      "op": "fact",
                      "path": "/vendor/riskScore",
                      "operator": "greater-than-or-equal",
                      "value": "90"
                    }
                  ]
                },
                {
                  "op": "all",
                  "conditions": [
                    {
                      "op": "fact",
                      "path": "/vendor/countryRisk",
                      "operator": "equals",
                      "value": "HIGH"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/riskScore",
                      "operator": "greater-than-or-equal",
                      "value": "70"
                    }
                  ]
                },
                {
                  "op": "all",
                  "conditions": [
                    {
                      "op": "fact",
                      "path": "/vendor/countryRisk",
                      "operator": "equals",
                      "value": "LOW"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/riskScore",
                      "operator": "less-than",
                      "value": "40"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/requestedSpend",
                      "operator": "less-than-or-equal",
                      "value": "500000.00"
                    }
                  ]
                },
                {
                  "op": "all",
                  "conditions": [
                    {
                      "op": "fact",
                      "path": "/vendor/countryRisk",
                      "operator": "equals",
                      "value": "LOW"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/riskScore",
                      "operator": "less-than",
                      "value": "40"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/requestedSpend",
                      "operator": "greater-than",
                      "value": "500000.00"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/requestedSpend",
                      "operator": "less-than-or-equal",
                      "value": "2000000.00"
                    },
                    {
                      "op": "evidence-present",
                      "evidenceRequirement": "insurance-certificate"
                    }
                  ]
                },
                {
                  "op": "all",
                  "conditions": [
                    {
                      "op": "fact",
                      "path": "/vendor/countryRisk",
                      "operator": "equals",
                      "value": "LOW"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/riskScore",
                      "operator": "less-than",
                      "value": "40"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/requestedSpend",
                      "operator": "greater-than",
                      "value": "500000.00"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/requestedSpend",
                      "operator": "less-than-or-equal",
                      "value": "2000000.00"
                    },
                    {
                      "op": "not",
                      "condition": {
                        "op": "evidence-present",
                        "evidenceRequirement": "insurance-certificate"
                      }
                    }
                  ]
                },
                {
                  "op": "all",
                  "conditions": [
                    {
                      "op": "fact",
                      "path": "/vendor/countryRisk",
                      "operator": "equals",
                      "value": "LOW"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/riskScore",
                      "operator": "greater-than-or-equal",
                      "value": "40"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/riskScore",
                      "operator": "less-than",
                      "value": "70"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/requestedSpend",
                      "operator": "less-than-or-equal",
                      "value": "100000.00"
                    }
                  ]
                },
                {
                  "op": "all",
                  "conditions": [
                    {
                      "op": "fact",
                      "path": "/vendor/countryRisk",
                      "operator": "equals",
                      "value": "MEDIUM"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/riskScore",
                      "operator": "less-than",
                      "value": "40"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/requestedSpend",
                      "operator": "less-than-or-equal",
                      "value": "100000.00"
                    }
                  ]
                }
              ]
            }
          }
        ]
      },
      "outcome": "review",
      "onUnknown": "escalate"
    }
  ],
  "exceptions": [
    {
      "id": "x-o3-large-high-country-exposure",
      "description": "O3 directly escalates a clear-screened high-country-risk request above 2000000 dollars.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "fact",
            "path": "/vendor/countryRisk",
            "operator": "equals",
            "value": "HIGH"
          },
          {
            "op": "fact",
            "path": "/vendor/requestedSpend",
            "operator": "greater-than",
            "value": "2000000.00"
          }
        ]
      },
      "effect": "escalate",
      "onUnknown": "escalate"
    },
    {
      "id": "x-o2-critical-supplier",
      "description": "O2 forces review for a clear-screened critical supplier unless O3 escalates.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "fact",
            "path": "/vendor/criticalSupplier",
            "operator": "equals",
            "value": "yes"
          }
        ]
      },
      "effect": "force-outcome",
      "outcome": "review",
      "onUnknown": "ignore"
    },
    {
      "id": "x-o1-suspend-d6c",
      "description": "O1 suppresses D6c for a reported new vendor.",
      "when": {
        "op": "fact",
        "path": "/vendor/newVendor",
        "operator": "equals",
        "value": "yes"
      },
      "effect": "suppress-rule",
      "targetRule": "r-d6c-low-moderate-small",
      "onUnknown": "ignore"
    },
    {
      "id": "x-d5-suppress-d6a",
      "description": "D5 prevents D6a from competing with prior-enforcement rejection.",
      "when": {
        "op": "fact",
        "path": "/vendor/priorEnforcement",
        "operator": "equals",
        "value": "yes"
      },
      "effect": "suppress-rule",
      "targetRule": "r-d6a-low-risk-low-spend",
      "onUnknown": "ignore"
    },
    {
      "id": "x-d5-suppress-d6b-insured",
      "description": "D5 prevents insured D6b approval from competing with prior-enforcement rejection.",
      "when": {
        "op": "fact",
        "path": "/vendor/priorEnforcement",
        "operator": "equals",
        "value": "yes"
      },
      "effect": "suppress-rule",
      "targetRule": "r-d6b-insured",
      "onUnknown": "ignore"
    },
    {
      "id": "x-d5-suppress-d6b-uninsured",
      "description": "D5 prevents D6b enhanced review from competing with prior-enforcement rejection.",
      "when": {
        "op": "fact",
        "path": "/vendor/priorEnforcement",
        "operator": "equals",
        "value": "yes"
      },
      "effect": "suppress-rule",
      "targetRule": "r-d6b-uninsured",
      "onUnknown": "ignore"
    },
    {
      "id": "x-d5-suppress-d6c",
      "description": "D5 prevents D6c approval from competing with prior-enforcement rejection.",
      "when": {
        "op": "fact",
        "path": "/vendor/priorEnforcement",
        "operator": "equals",
        "value": "yes"
      },
      "effect": "suppress-rule",
      "targetRule": "r-d6c-low-moderate-small",
      "onUnknown": "ignore"
    },
    {
      "id": "x-d5-suppress-o1-review",
      "description": "D5 prevents O1's D6c review result from competing with prior-enforcement rejection.",
      "when": {
        "op": "fact",
        "path": "/vendor/priorEnforcement",
        "operator": "equals",
        "value": "yes"
      },
      "effect": "suppress-rule",
      "targetRule": "r-o1-new-vendor-review",
      "onUnknown": "ignore"
    },
    {
      "id": "x-d5-suppress-d7",
      "description": "D5 prevents D7 approval from competing with prior-enforcement rejection.",
      "when": {
        "op": "fact",
        "path": "/vendor/priorEnforcement",
        "operator": "equals",
        "value": "yes"
      },
      "effect": "suppress-rule",
      "targetRule": "r-d7-medium-low-risk-small",
      "onUnknown": "ignore"
    },
    {
      "id": "x-d5-suppress-d8",
      "description": "D5 prevents default review from competing with prior-enforcement rejection.",
      "when": {
        "op": "fact",
        "path": "/vendor/priorEnforcement",
        "operator": "equals",
        "value": "yes"
      },
      "effect": "suppress-rule",
      "targetRule": "r-d8-review",
      "onUnknown": "ignore"
    }
  ],
  "escalation": {
    "triggers": [
      "missing-required-evidence",
      "no-match",
      "unknown"
    ],
    "target": {
      "kind": "queue",
      "name": "vendor-compliance-desk"
    }
  }
}
```

